// @concept:concept-driven-tests @concept:governance-mode @concept:reference-sync @concept:concept-code-mapping
import { z } from 'zod';

export const LocaleSchema = z.enum(['ko', 'en']);
export type Locale = z.infer<typeof LocaleSchema>;

// 두 기본값은 용도가 다르다 — 헷갈리지 말 것.
// - LEGACY_LOCALE: init.json에 locale 키가 없을 때 "읽는" 값. 키 없는 기존 프로젝트는 한국어로 유지한다
//   (스키마 default·빈칸 채우기·설정을 못 읽은 폴백이 모두 이 값을 쓴다).
// - NEW_PROJECT_LOCALE: 새로 `init`할 때 init.json에 "써 넣는" 값(영어 기본, 한국어는 번역본).
export const LEGACY_LOCALE: Locale = 'ko';
export const NEW_PROJECT_LOCALE: Locale = 'en';

/** 설정(없거나 깨졌으면 null)에서 출력 언어를 정한다 — 읽을 수 없으면 기존 프로젝트 기본(LEGACY_LOCALE). */
export function localeOf(cfg: { locale?: Locale } | null | undefined): Locale {
  return cfg?.locale ?? LEGACY_LOCALE;
}

// 커밋 게이트 강도(governance-mode 개념): strict=차단, standard=확인(기본), light=경고만.
// 설정이 없거나 깨졌으면 항상 standard로 동작한다(안전한 쪽).
export const EnforcementSchema = z.enum(['strict', 'standard', 'light']);
export type Enforcement = z.infer<typeof EnforcementSchema>;

export const InitConfigSchema = z.object({
  version: z.string(),
  enabled: z.literal(true),
  locale: LocaleSchema.default(LEGACY_LOCALE),
  versionCheck: z.boolean().default(true),
  // 테스트 코드도 개념의 지배를 받는다 — 켜져 있으면(기본) 세션 시작 규칙에
  // "테스트 작성 전 대상 코드의 개념을 찾아 규칙 기반 시나리오를 도출하라"가 주입된다.
  conceptDrivenTests: z.boolean().default(true),
  // 어떤 파일을 "검사(테스트)"로 볼지 정하는 이름 규칙 — concept-driven-tests의 두 문지기
  // (개념이 바뀌면 딸린 검사가 따라왔는지 / 검사 파일이 어떤 개념을 가리키는지)가 함께 쓴다.
  // 적지 않으면 흔히 쓰는 기본 규칙을 쓴다.
  testGlobs: z
    .array(z.string())
    .default([
      'tests/**',
      'test/**',
      '__tests__/**',
      '**/*.test.*',
      '**/*.spec.*',
      '**/*_test.*',
      '**/*_spec.*',
      '**/test_*.py',
    ]),
  enforcement: EnforcementSchema.default('standard'),
  // 참고자료 기준점(파일 이름·지문 목록)을 저장소에 올릴지(shared, 기본) 내 컴퓨터에만 둘지(local).
  // 내용은 어느 쪽에도 담기지 않는다 — 파일 이름까지 숨겨야 하면 local로 둔다.
  referenceLock: z.enum(['local', 'shared']).default('shared'),
  // 커밋 게이트가 @concept 마커를 강제하지 않는 경로 글롭 — **재생성물·외부 코드만** 자동 제외한다.
  // 손으로 쓴 코드(utils/types/config/scripts 포함)는 예외 없이 마커가 있어야 하며,
  // 개념이 없으면 `@concept:none`을 명시한다(조용히 건너뛰지 않는다).
  ignoreGlobs: z.array(z.string()).default([
    'docs/conceptpowers/**', // 플러그인 생성물(뷰어 등)
    'dist/**',
    'build/**', // 빌드 산출물
    'node_modules/**', // 외부 의존성
    '**/*.generated.*', // 코드 생성물
  ]),
  // 개념 없음 영역(concept-code-mapping) — 공통 UI처럼 따를 개념이 없는 손코드가 모인 폴더.
  // 그 안에서 표식이 없는 파일은 `@concept:none`을 단 것으로 친다. ignoreGlobs와 달리 감사에서
  // 빼지 않는다 — 표식을 달면 그 표식을 따르고, 태그 정합성 검사도 그대로 받는다.
  noConceptGlobs: z.array(z.string()).default([]),
});
// 모르는 키는 거부하지 않고 버린다(zod 기본 strip) — 읽히지 않아 빠진 옛 키
// (backfillMode·enforceScope·project)가 기존 init.json에 남아 있어도 검증은 통과한다.
export type InitConfig = z.infer<typeof InitConfigSchema>;

// 설정이 없거나 깨졌을 때 쓰는 기본 제외 글롭. 문지기·결산·감사가 같은 잣대를 쓰도록
// 폴백을 한 곳에 모은다(호출마다 새 배열이므로 공유 참조가 변형될 일은 없다).
export function defaultIgnoreGlobs(): string[] {
  return InitConfigSchema.shape.ignoreGlobs.parse(undefined);
}
export function parseInitConfig(input: unknown): InitConfig {
  return InitConfigSchema.parse(input);
}
